// Verify X-Play-Review-Signature and turn the body (one payload, or an array when the
// channel has batch: true) into one n8n item per event.
// Set PLAY_REVIEW_WEBHOOK_SECRET in n8n's environment and allow $env access
// (N8N_BLOCK_ENV_ACCESS_IN_NODE=false), or hard-code the secret here for a quick test.
const crypto = require('crypto');
const secret = $env.PLAY_REVIEW_WEBHOOK_SECRET;
const req = $input.first().json;
const ts = req.headers['x-play-review-timestamp'];
const sig = req.headers['x-play-review-signature'];
const body = req.body;
if (secret) {
  // The sender signs the compact JSON body; re-serialising the parsed body reproduces it.
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${JSON.stringify(body)}`).digest('hex');
  if (sig !== expected) throw new Error('invalid X-Play-Review-Signature');
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('stale timestamp');
}
const payloads = Array.isArray(body) ? body : [body];
return payloads.map((p) => ({ json: p }));
